import CategoryTheory.ProjectiveResolution

open CategoryTheory

theorem lg_target {C : Type u} [CategoryTheory.Category.{v, u} C] [CategoryTheory.Abelian C] [CategoryTheory.EnoughProjectives C] : CategoryTheory.HasProjectiveResolutions C := by
  intro X
  let P : ChainComplex₀ C ℕ := (zeroChainComplex X)
  let exact_at : ∀ n : ℕ, ExactAt P n :=
    begin
      intro n,
      cases n,
      case zero { exact ExactAt.zeroChainComplex P }
      case (succ n) { exact ExactAt.succChainComplex P }
    end
  let zeroth_term_eq_X : P 0 ≅ X := eqOfIsomorphism (zeroChainComplex.isomorphism X)
  let resolution : ProjectiveResolution C X := {
    complex := P,
    exact_at := exact_at,
    zeroth_term_eq_X := zeroth_term_eq_X,
  }
  exact resolution

